const root = dirname(fileURLToPath(import.meta.url));
const output = join(root, 'dist');
const staging = join(root, 'dist-building');
const business = JSON.parse(await readFile(join(root, 'business.json'), 'utf8'));
const googleReviews = business.googleReviews;
const reviewRating = new Intl.NumberFormat('nl-NL', { minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(googleReviews.rating);
const reviewCheckedOn = new Intl.DateTimeFormat('nl-NL', { timeZone: 'UTC' }).format(new Date(`${googleReviews.checkedOn}T12:00:00Z`));
const assetVersion = createHash('sha256').update(await readFile(join(root, 'styles.css'))).update(await readFile(join(root, 'site.js'))).digest('hex').slice(0, 12);
const socialImage = await readFile(join(root, 'public/assets/img/og-image.jpg'));
const socialImageName = `og-image-${createHash('sha256').update(socialImage).digest('hex').slice(0, 12)}.jpg`;
const socialImagePath = `/assets/${socialImageName}`;
const socialImageAlt = `${business.name} - ${business.phone}`;
const pricing = JSON.parse(await readFile(join(root, 'pricing.json'), 'utf8'));
const euro = (amount) => new Intl.NumberFormat('nl-NL', { style: 'currency', currency: 'EUR', minimumFractionDigits: Number.isInteger(amount) ? 0 : 2, maximumFractionDigits: 2 }).format(amount).replace(/\u00a0/g, ' ');
const withVat = (amount) => amount * (1 + pricing.vatRate);
const dayPrice = pricing.businessHourly * pricing.dayHours;
const privateDayPrice = pricing.privateHourly * pricing.dayHours;
const privateMinimumLabour = pricing.privateHourly * pricing.privateMinimumHours;
const escape = (value) => String(value).replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
const icons = new Map();
async function loadIcons() {
  for (const name of ['arrow-up-right', 'arrow-right', 'arrow-left', 'phone', 'mail', 'menu', 'check', 'file-text', 'copy', 'map-pin', 'message-circle', 'star', 'plus', 'x', 'building-2', 'house', 'hard-hat', 'users-round', 'expand', 'lightbulb', 'plug', 'cable', 'battery-charging', 'clock-3', 'calendar-days', 'play', 'pause']) {
    const svg = await readFile(join(root, 'node_modules/lucide-static/icons', `${name}.svg`), 'utf8');
    icons.set(name, svg.replace('<svg', '<svg class="icon" aria-hidden="true" focusable="false"'));
  }
}
await loadIcons();
const icon = (name) => icons.get(name);
const button = (href, label, style = 'primary', glyph = 'arrow-up-right') => `<a class="button button--${style}" href="${escape(href)}">${escape(label)}${icon(glyph)}</a>`;
