const googleReviewLink = () => `<a data-google-reviews class="google-review-link" href="${escape(googleReviews.sourceUrl)}" target="_blank" rel="noopener noreferrer" aria-label="Google: ${reviewRating} van 5 op basis van ${googleReviews.count} reviews. Stand ${reviewCheckedOn}. Bekijk op Google Maps.">${icon('star')}<span><span class="google-review-summary"><strong>${reviewRating}/5</strong> · ${googleReviews.count} reviews op Google</span><small>Stand <time datetime="${googleReviews.checkedOn}">${reviewCheckedOn}</time></small></span>${icon('arrow-up-right')}</a>`;
