const travelPricing = (privateClient = false) => `<div class="travel-pricing"><div><h3>Reisbijdrage vooraf bekend.</h3><p>Afstand enkele reis over de weg vanaf Veenendaal. Eén afgesproken retourrit per voertuig per werkdag, inclusief reistijd en vervoer.</p></div><div class="travel-table-wrap"><table class="travel-table"><caption>Reisbijdrage en rekenvoorbeeld voor ${pricing.dayHours} werkuren, ${privateClient ? 'incl. 21% btw' : 'excl. btw'}</caption><thead><tr><th scope="col">Vanaf Veenendaal</th><th scope="col">Reisbijdrage</th><th scope="col">${pricing.dayHours} uur + reis*</th></tr></thead><tbody>${pricing.travelZones.map((zone, index) => `<tr><th scope="row"><span class="travel-zone-name">${['Lokaal', 'Regio', 'Verder weg'][index]}</span><span class="travel-zone-distance">${zone.label}</span></th><td>${euro(privateClient ? withVat(zone.fee) : zone.fee)}</td><td>${euro(privateClient ? withVat(privateDayPrice + zone.fee) : dayPrice + zone.fee)}</td></tr>`).join('')}</tbody></table><p class="privacy-note">* Eén monteur, ${pricing.dayHours} werkuren op locatie en één voertuig. Exclusief materialen, speciale hulpmiddelen en parkeren. Boven 100 km, meerdere locaties of overnachting: offerte op maat. Binnen een vaste projectprijs nemen we de afgesproken reis- en projectkosten op in het totaal.</p></div></div>`;
const priceFlexibility = () => `<p class="price-flexibility"><strong>Prijsafspraken zijn bespreekbaar.</strong> We kijken naar de omvang, looptijd, planning en teambezetting. De definitieve prijs en voorwaarden leggen we vóór de start vast in uw offerte.</p>`;
const privateVisitMinimum = () => `<div class="private-visit-minimum" id="minimumbezoek">
  <h3>Minimum per afgesproken montagebezoek.</h3>
  <p>Voor een afzonderlijk bezoek op regie binnen een aangenomen woningproject rekenen we minimaal ${pricing.privateMinimumHours} arbeidsuren voor één monteur, plus één reisbijdrage. Bij 1,5 uur werk betaalt u dus ${pricing.privateMinimumHours} uur; bij 3 uur werk betaalt u 3 uur. Het minimum komt niet boven op de gewerkte uren.</p>
  <table class="travel-table visit-minimum-table"><caption>Minimumtotaal voor één monteur, inclusief 21% btw en één retourrit</caption><thead><tr><th scope="col">Afstand vanaf Veenendaal</th><th scope="col">Reisbijdrage</th><th scope="col">Totaal</th></tr></thead><tbody>${pricing.travelZones.filter(zone => zone.maxKm <= pricing.privateShortVisitMaxKm).map(zone => `<tr data-private-visit-zone="${zone.maxKm}"><th scope="row">${zone.label}</th><td>${euro(withVat(zone.fee))}</td><td>${euro(withVat(privateMinimumLabour + zone.fee))}</td></tr>`).join('')}</tbody></table>
  <p class="privacy-note">Deze totalen bevatten ${euro(withVat(privateMinimumLabour))} arbeid en de getoonde reisbijdrage; voor die rit komt er geen extra voorrijtoeslag bij. Afstand enkele reis over de weg. De reisbijdrage geldt per voertuig per werkdag. Na de minimumduur rekenen we de werkelijk gewerkte uren tegen het afgesproken uurtarief.</p>
  <p class="privacy-note">Materialen, bijzondere hulpmiddelen en eventueel parkeren bevestigen we vooraf. Boven ${pricing.privateShortVisitMaxKm} km plannen we alleen een groter werkblok op offerte. Extra teambezetting en het bijbehorende minimum spreken we apart af.</p>
  <p class="privacy-note">Geen extra minimumtoeslag op een vaste projectofferte of voor herstel van onze eigen uitvoeringsfouten. Een eventueel betaald opnamebezoek spreken we afzonderlijk af. De prijs bevestigen we vóór uw akkoord; dit is geen spoed- of reparatieservice.</p>
</div>`;
const teamPricing = (privateClient = false) => `<details class="rate-disclosure price-regie team-pricing" id="${privateClient ? 'particulier-teamtarief' : 'teamtarief'}"><summary>Tarief per rol of één teamtarief ${icon('plus')}</summary><div class="regie-content"><div class="team-pricing-options"><div><h3>Tarief per rol</h3><p>Een afzonderlijk uurtarief voor de ervaren monteur, hulpmonteur of tweede monteur, passend bij de taken en ervaring.</p></div><div><h3>Eén gemiddeld teamtarief</h3><p>Eén afgesproken uurtarief per persoon binnen het afgesproken team. Ook mogelijk bij een ervaren monteur met een minder ervaren collega.</p></div></div><p>De offerte vermeldt de teamsamenstelling, het ervaringsniveau, de taakverdeling en de technische begeleiding. Het teamtarief geldt voor die bezetting en werkzaamheden; specialistische inzet offreren we apart.</p><p class="team-rate-calculation"><strong>Per persoon, niet per ploeguur.</strong> Twee personen die ieder 8 uur werken, tellen samen als 16 persoonsuren. We rekenen de werkelijk gewerkte uren; extra inzet alleen na akkoord.</p><p>De offerte vermeldt ${privateClient ? 'bedragen inclusief btw en alle afgesproken projectkosten' : 'bedragen exclusief btw en de afgesproken bijkomende kosten'}. De reisbijdrage is per voertuig, niet per persoon.</p>${button(`/contact?${privateClient ? 'type=particulier&' : ''}prijs=teamtarief#aanvraag`, 'Bespreek een teamtarief', 'secondary')}</div></details>`;
const pricingSection = () => `<section class="section section--muted pricing-section" id="tarieven"><div class="container">
  <div class="quote-led-layout"><div><p class="eyebrow">Zakelijke prijsafspraken</p><h2>Een offerte voor het afgesproken resultaat.</h2><p>Op basis van uw tekeningen, hoeveelheden en planning maken we een voorstel voor het complete werkpakket.</p>${button(contact, 'Vraag een projectofferte')}</div><ul class="quote-scope-list"><li><strong>Per project of fase</strong><span>Een vaste aanneemsom voor duidelijk afgebakend werk.</span></li><li><strong>Per woning of unit</strong><span>Eenheidsprijzen voor herhaalbaar werk, op basis van dezelfde specificaties.</span></li><li><strong>Afspraken vóór de start</strong><span>Materialen, reis- en projectkosten vastleggen. Meerwerk alleen na overleg en akkoord.</span></li></ul></div>
  ${priceFlexibility()}
  <details class="rate-disclosure price-regie" id="uur-reis" data-rate="uur-reis"><summary>Liever op regie? Uurtarief en kosten ${icon('plus')}</summary><div class="regie-content"><h3>Standaard projectmontage</h3><p class="reference-rate"><strong>${euro(pricing.businessHourly)} per uur</strong> <span>indicatief, excl. btw, per monteur</span></p><p>Een referentietarief voor standaard montage volgens tekeningen, inclusief eigen standaardgereedschap. Het is geen universeel tarief voor iedere rol of specialisatie; een teamtarief spreken we afzonderlijk af.</p>${checklist(rateOptions[1].terms)}<p id="dagtarief" data-rate="dagtarief">Rekenvoorbeeld per monteur bij dit referentietarief: ${pricing.dayHours} werkuren op locatie: ${euro(dayPrice)} excl. btw. Materialen en reisbijdrage komen erbij; pauzes en reistijd zijn geen werkuren op locatie.</p><div class="actions">${button('/contact?prijs=uur-reis#aanvraag', 'Bespreek werken op regie', 'secondary')}<a class="text-link" href="/contact?prijs=dagtarief#aanvraag">Vraag een projectdag aan ${icon('arrow-right')}</a></div>${travelPricing()}<div class="rate-terms"><p>Ook voor grotere projecten buiten de regio. De route, prijs en planning bevestigen we vooraf; uw aanvraag is nog geen boeking. De reisbijdrage is per voertuig, niet per monteur. Extra ritten, speciale hulpmiddelen, parkeren en eventuele overnachting spreken we vooraf af.</p><p>Zakelijke bedragen zijn excl. btw. Waar de verleggingsregeling geldt, factureren we met btw verlegd; anders brengen we de toepasselijke btw in rekening.</p></div></div></details>
  ${teamPricing()}
  <p class="pricing-private-note">${icon('house')}<span>Een grote verbouwing of nieuwbouw? <a href="/woningprojecten#prijsafspraak">Particuliere prijsafspraken, inclusief btw</a>.</span></p>
</div></section>`;
const homePricing = () => `<section class="section section--muted home-pricing" id="tarieven"><div class="container"><div class="section-heading heading-row"><div><p class="eyebrow">Heldere prijsafspraken</p><h2>Eerst de scope. Dan een heldere prijs.</h2></div><p>Een totaalofferte voor uw project. Of werken op regie, met een prijsafspraak die past bij de opdracht.</p></div><div class="price-methods"><article>${icon('file-text')}<h3>Vaste projectprijs</h3><p>Een afgesproken bedrag voor uw werkpakket, projectfase of complete woninginstallatie.</p></article><article>${icon('clock-3')}<h3>Werken op regie</h3><p>Vooraf duidelijk welke werkzaamheden, uren en bijkomende kosten we afspreken.</p></article><article>${icon('users-round')}<h3>Team op maat</h3><p>Een ervaren monteur, eventueel met hulpmonteur of tweede monteur. Tarieven per rol of één gemiddeld uurtarief per persoon voor het afgesproken team.</p></article></div><p class="price-flexibility">Prijsafspraken zijn bespreekbaar. De definitieve prijs, bezetting en voorwaarden bevestigen we in uw offerte.</p><div class="home-price-links"><a class="text-link" href="/zakelijk#tarieven">Zakelijke prijsafspraken ${icon('arrow-right')}</a><a class="text-link" href="/woningprojecten#prijsafspraak">Particuliere prijsafspraken ${icon('arrow-right')}</a></div></div></section>`;
