const serviceOverview = () => `<section class="section section--muted service-overview" id="alle-werkzaamheden"><div class="container"><div class="section-heading"><p class="eyebrow">Het volledige overzicht</p><h2>Wat we verder uitvoeren.</h2><p>Deze werkzaamheden combineren we binnen zakelijke opdrachten en grotere woningprojecten.</p></div><div class="service-overview-grid">${serviceCatalogue.map(group => `<section class="service-group"><h3>${icon(group.glyph)}${escape(group.title)}</h3><ul>${group.items.map(item => `<li id="${item.id}"><a href="/contact?werk=${item.id}#aanvraag">${escape(item.title)}${icon('arrow-up-right')}</a></li>`).join('')}</ul></section>`).join('')}</div><p class="scope-note">De technische mogelijkheden en omvang stemmen we vooraf af. De netbeheerder verzorgt een eventuele verzwaring van de netaansluiting. Bij warmtepompen, zonnepanelen en thuisbatterijen gaat het om de afgesproken elektrotechnische werkzaamheden.</p></div></section>`;
