const crewSection = () => `<section class="section crew-section" id="bezetting"><div class="container"><div class="section-heading heading-row"><div><p class="eyebrow">Bezetting op maat</p><h2>Meer capaciteit. Eén aanspreekpunt.</h2></div><p>Een ervaren monteur of een passend montageteam. Elektoria stemt de uitvoering en technische begeleiding af op uw werkpakket.</p></div><div class="crew-grid">${crewChoices.map(item => `<article data-crew-package="${item.id}">${icon(item.glyph)}<h3><a href="/contact?bezetting=${item.id}#aanvraag">${escape(item.title)}${icon('arrow-up-right')}</a></h3><p>${escape(item.text)}</p></article>`).join('')}</div><p class="crew-note">Samenstelling, beschikbaarheid, taakverdeling en begeleiding bevestigen we vóór de start. Extra inzet alleen na akkoord. Een <a href="#teamtarief">tarief per rol of één gemiddeld teamtarief</a> spreken we vooraf af.</p></div></section>`;
