const copyPhoto = async (file) => {
  const relative = `${file}.webp`;
  const source = file.startsWith('media/') ? join(root, relative) : file.startsWith('work-photos/')
    ? join(root, 'public/assets', relative)
    : join(root, 'public/assets/img', relative);
  const target = join(staging, 'assets', relative);
  await mkdir(dirname(target), { recursive: true });
  await cp(source, target);
};
selectedPhotos.add('media/maksym-usyk-natural-portrait-v3');
for (const file of selectedPhotos) await copyPhoto(file);
